    #[test]
    fn test_pagerank_two_nodes_symmetric() {
        // 0 -> 1 and 1 -> 0
        let edges = vec![vec![1], vec![0]];
        let config = PageRankConfig::default();
        let pr = power_iteration_pagerank(2, &edges, &config);

        assert_eq!(pr.len(), 2);
        assert!((pr[0] - 0.5).abs() < 1e-6);
        assert!((pr[1] - 0.5).abs() < 1e-6);
        assert!((pr[0] + pr[1] - 1.0).abs() < 1e-6);
    }

    #[test]
    fn test_pagerank_three_nodes_flow() {
        // 0 -> 1, 0 -> 2
        // 1 -> 2
        // 2 -> 0
        // Node 2 has highest incoming authority
        let edges = vec![vec![1, 2], vec![2], vec![0]];
        let config = PageRankConfig::default();
        let pr = power_iteration_pagerank(3, &edges, &config);

        assert_eq!(pr.len(), 3);
        let sum: f64 = pr.iter().sum();
        assert!((sum - 1.0).abs() < 1e-6);
        assert!(pr[2] > pr[0]);
        assert!(pr[2] > pr[1]);
    }

    #[test]
    fn test_pagerank_dangling_node_mass_preservation() {
        // 0 -> 1; 1 has no outgoing links (dangling)
        let edges = vec![vec![1], vec![]];
        let config = PageRankConfig::default();
        let pr = power_iteration_pagerank(2, &edges, &config);

        assert_eq!(pr.len(), 2);
        let sum: f64 = pr.iter().sum();
        assert!((sum - 1.0).abs() < 1e-6);
        // Node 1 receives incoming link from 0, so pr[1] > pr[0]
        assert!(pr[1] > pr[0]);
    }

    #[test]
    fn test_pagerank_empty_and_single_node() {
        let config = PageRankConfig::default();
        assert_eq!(power_iteration_pagerank(0, &[], &config), Vec::<f64>::new());
        assert_eq!(power_iteration_pagerank(1, &[vec![]], &config), vec![1.0]);
    }

    #[test]
    fn test_final_score_formula() {
        let bm25: f64 = 4.0;
        let pr: f64 = 0.05;
        let alpha: f64 = 0.7;
        let epsilon: f64 = 1e-6;

        let expected = alpha * bm25 + (1.0 - alpha) * (pr + epsilon).ln();
        let computed = final_score(bm25, pr, alpha, epsilon);

        assert!((computed - expected).abs() < 1e-10);
    }

    #[test]
    fn test_final_score_alpha_bounds() {
        let bm25: f64 = 5.5;
        let pr: f64 = 0.02;
        let epsilon: f64 = 1e-6;

        // When alpha = 1.0, score must equal pure BM25
        let score_pure_bm25 = final_score(bm25, pr, 1.0, epsilon);
        assert!((score_pure_bm25 - bm25).abs() < 1e-10);

        // When alpha = 0.0, score must equal pure log(PageRank + epsilon)
        let score_pure_pr = final_score(bm25, pr, 0.0, epsilon);
        assert!((score_pure_pr - (pr + epsilon).ln()).abs() < 1e-10);
    }

    #[test]
    fn test_binary_index_pagerank_roundtrip() {
        let test_path = "target/test_pagerank_index.bin";
        let total_docs = 3;
        let avg_doc_length = 50.0;
        let doc_lengths = vec![40, 50, 60];
        let pagerank = vec![0.2, 0.5, 0.3];
        let doc_metadata = vec![
            DocMetadata {
                internal_id: 0,
                hex_id: "000001".to_string(),
                url: "https://example.com/1".to_string(),
                title: "Doc 1".to_string(),
                length: 40,
                pagerank: 0.2,
            },
            DocMetadata {
                internal_id: 1,
                hex_id: "000002".to_string(),
                url: "https://example.com/2".to_string(),
                title: "Doc 2".to_string(),
                length: 50,
                pagerank: 0.5,
            },
            DocMetadata {
                internal_id: 2,
                hex_id: "000003".to_string(),
                url: "https://example.com/3".to_string(),
                title: "Doc 3".to_string(),
                length: 60,
                pagerank: 0.3,
            },
        ];
        let sorted_terms = vec!["term".to_string()];
        let mut inverted_index = HashMap::new();
        inverted_index.insert(
            "term".to_string(),
            vec![Posting {
                doc_id: 0,
                term_frequency: 1,
                positions: vec![0],
            }],
        );

        BinaryIndexWriter::write_index(
            test_path,
            total_docs,
            avg_doc_length,
            &doc_lengths,
            &pagerank,
            &doc_metadata,
            &sorted_terms,
            &inverted_index,
        )
        .expect("write_index failed");

        let mmap_index = MmapIndex::open(test_path).expect("open failed");
        assert_eq!(mmap_index.total_docs, total_docs);
        assert!((mmap_index.get_pagerank(0) - 0.2).abs() < 1e-9);
        assert!((mmap_index.get_pagerank(1) - 0.5).abs() < 1e-9);
        assert!((mmap_index.get_pagerank(2) - 0.3).abs() < 1e-9);

        let meta1 = mmap_index.get_doc_meta(1).expect("meta 1 missing");
        assert!((meta1.pagerank - 0.5).abs() < 1e-9);
        assert_eq!(meta1.title, "Doc 2");

        let _ = std::fs::remove_file(test_path);
    }

    #[test]
    fn test_quoted_query_search_integration() {
        let test_index_path = "target/test_quoted_search_index.bin";
        let test_fst_path = "target/test_quoted_search_dict.fst";

        let total_docs = 3;
        let avg_doc_length = 10.0;
        let doc_lengths = vec![10, 10, 10];
        let pagerank = vec![0.33, 0.33, 0.34];
        let doc_metadata = vec![
            DocMetadata {
                internal_id: 0,
                hex_id: "doc0".to_string(),
                url: "https://example.com/0".to_string(),
                title: "Distributed Systems Intro".to_string(),
                length: 10,
                pagerank: 0.33,
            },
            DocMetadata {
                internal_id: 1,
                hex_id: "doc1".to_string(),
                url: "https://example.com/1".to_string(),
                title: "Systems That Are Distributed".to_string(),
                length: 10,
                pagerank: 0.33,
            },
            DocMetadata {
                internal_id: 2,
                hex_id: "doc2".to_string(),
                url: "https://example.com/2".to_string(),
                title: "Unrelated Topic".to_string(),
                length: 10,
                pagerank: 0.34,
            },
        ];

        // Doc 0: "distribut" at pos 0, "system" at pos 1 (consecutive)
        // Doc 1: "system" at pos 0, "distribut" at pos 4 (non-consecutive and reversed)
        let mut inverted_index = HashMap::new();
        inverted_index.insert(
            "distribut".to_string(),
            vec![
                Posting {
                    doc_id: 0,
                    term_frequency: 1,
                    positions: vec![0],
                },
                Posting {
                    doc_id: 1,
                    term_frequency: 1,
                    positions: vec![4],
                },
            ],
        );
        inverted_index.insert(
            "system".to_string(),
            vec![
                Posting {
                    doc_id: 0,
                    term_frequency: 1,
                    positions: vec![1],
                },
                Posting {
                    doc_id: 1,
                    term_frequency: 1,
                    positions: vec![0],
                },
            ],
        );

        let mut sorted_terms = vec!["distribut".to_string(), "system".to_string()];
        sorted_terms.sort();

        BinaryIndexWriter::write_index(
            test_index_path,
            total_docs,
            avg_doc_length,
            &doc_lengths,
            &pagerank,
            &doc_metadata,
            &sorted_terms,
            &inverted_index,
        )
        .expect("write_index failed");

        let fst_file = File::create(test_fst_path).expect("create fst failed");
        let fst_writer = BufWriter::new(fst_file);
        let mut builder = MapBuilder::new(fst_writer).expect("mapbuilder failed");
        for (term_idx, term) in sorted_terms.iter().enumerate() {
            builder
                .insert(term.as_bytes(), term_idx as u64)
                .expect("insert term");
        }
        builder.finish().expect("finish fst");

        let mmap_index = MmapIndex::open(test_index_path).expect("open index failed");
        let dictionary = TermDictionary::open(test_fst_path).expect("open dict failed");
        let pipeline = TokenizerPipeline::new();

        // 1. Quoted query: "distributed systems" -> only doc 0 matches
        let quoted_res = search_combined_mmap(
            "\"distributed systems\"",
            &mmap_index,
            &dictionary,
            &pipeline,
            1.0,
            DEFAULT_EPSILON,
            10,
        );
        assert_eq!(quoted_res.len(), 1);
        assert_eq!(quoted_res[0].0.hex_id, "doc0");

        // 2. Reversed quoted query: "systems distributed" -> 0 hits
        let rev_res = search_combined_mmap(
            "\"systems distributed\"",
            &mmap_index,
            &dictionary,
            &pipeline,
            1.0,
            DEFAULT_EPSILON,
            10,
        );
        assert_eq!(rev_res.len(), 0);

        // 3. Unquoted query: distributed systems -> both doc 0 and doc 1 match
        let unquoted_res = search_combined_mmap(
            "distributed systems",
            &mmap_index,
            &dictionary,
            &pipeline,
            1.0,
            DEFAULT_EPSILON,
            10,
        );
        assert_eq!(unquoted_res.len(), 2);

        let _ = std::fs::remove_file(test_index_path);
        let _ = std::fs::remove_file(test_fst_path);
    }

    #[test]
    fn test_wand_posting_cursor_advance_and_read() {
        let mut buf = Vec::new();
        // doc 5, tf 1, pos [0]
        encode_vbyte(5, &mut buf);
        encode_vbyte(1, &mut buf);
        encode_vbyte(0, &mut buf);

        // doc 12 (delta 7), tf 2, pos [3, 8]
        encode_vbyte(7, &mut buf);
        encode_vbyte(2, &mut buf);
        encode_vbyte(3, &mut buf);
        encode_vbyte(5, &mut buf);

        // doc 30 (delta 18), tf 1, pos [10]
        encode_vbyte(18, &mut buf);
        encode_vbyte(1, &mut buf);
        encode_vbyte(10, &mut buf);

        // doc 45 (delta 15), tf 1, pos [2]
        encode_vbyte(15, &mut buf);
        encode_vbyte(1, &mut buf);
        encode_vbyte(2, &mut buf);

        let mut cursor = WandPostingCursor::new(&buf, 4, 2.0, 5.0);
        assert!(cursor.has_more);
        assert_eq!(cursor.current_doc_id, 5);
        assert_eq!(cursor.current_tf, 1);

        // Advance to doc 20 -> should land on doc 30
        assert!(cursor.advance_to(20));
        assert_eq!(cursor.current_doc_id, 30);
        assert_eq!(cursor.current_tf, 1);

        // Advance to 30 -> stays on 30
        assert!(cursor.advance_to(30));
        assert_eq!(cursor.current_doc_id, 30);

        // Advance to 40 -> lands on 45
        assert!(cursor.advance_to(40));
        assert_eq!(cursor.current_doc_id, 45);

        // Advance past all -> ends
        assert!(!cursor.advance_to(50));
        assert!(!cursor.has_more);
    }

    #[test]
    fn test_wand_multi_term_top_k_pruning() {
        let test_index_path = "target/test_wand_prune_index.bin";
        let test_fst_path = "target/test_wand_prune_dict.fst";

        let total_docs = 6;
        let avg_doc_length = 20.0;
        let doc_lengths = vec![20; 6];
        let pagerank = vec![1.0 / 6.0; 6];
        let doc_metadata: Vec<DocMetadata> = (0..6)
            .map(|i| DocMetadata {
                internal_id: i,
                hex_id: format!("doc{}", i),
                url: format!("https://example.com/{}", i),
                title: format!("Doc Title {}", i),
                length: 20,
                pagerank: 1.0 / 6.0,
            })
            .collect();

        // 3 terms:
        // "alpha": doc 0 (tf=5), doc 1 (tf=5), doc 2 (tf=1)
        // "beta": doc 0 (tf=5), doc 1 (tf=4), doc 3 (tf=1)
        // "gamma": doc 0 (tf=5), doc 4 (tf=1), doc 5 (tf=1)
        let mut inverted_index = HashMap::new();
        inverted_index.insert(
            "alpha".to_string(),
            vec![
                Posting {
                    doc_id: 0,
                    term_frequency: 5,
                    positions: vec![0, 1, 2, 3, 4],
                },
                Posting {
                    doc_id: 1,
                    term_frequency: 5,
                    positions: vec![0, 1, 2, 3, 4],
                },
                Posting {
                    doc_id: 2,
                    term_frequency: 1,
                    positions: vec![0],
                },
            ],
        );
        inverted_index.insert(
            "beta".to_string(),
            vec![
                Posting {
                    doc_id: 0,
                    term_frequency: 5,
                    positions: vec![0, 1, 2, 3, 4],
                },
                Posting {
                    doc_id: 1,
                    term_frequency: 4,
                    positions: vec![0, 1, 2, 3],
                },
                Posting {
                    doc_id: 3,
                    term_frequency: 1,
                    positions: vec![0],
                },
            ],
        );
        inverted_index.insert(
            "gamma".to_string(),
            vec![
                Posting {
                    doc_id: 0,
                    term_frequency: 5,
                    positions: vec![0, 1, 2, 3, 4],
                },
                Posting {
                    doc_id: 4,
                    term_frequency: 1,
                    positions: vec![0],
                },
                Posting {
                    doc_id: 5,
                    term_frequency: 1,
                    positions: vec![0],
                },
            ],
        );

        let mut sorted_terms = vec!["alpha".to_string(), "beta".to_string(), "gamma".to_string()];
        sorted_terms.sort();

        BinaryIndexWriter::write_index(
            test_index_path,
            total_docs,
            avg_doc_length,
            &doc_lengths,
            &pagerank,
            &doc_metadata,
            &sorted_terms,
            &inverted_index,
        )
        .expect("write_index failed");

        let fst_file = File::create(test_fst_path).expect("create fst failed");
        let fst_writer = BufWriter::new(fst_file);
        let mut builder = MapBuilder::new(fst_writer).expect("mapbuilder failed");
        for (term_idx, term) in sorted_terms.iter().enumerate() {
            builder
                .insert(term.as_bytes(), term_idx as u64)
                .expect("insert term");
        }
        builder.finish().expect("finish fst");

        let mmap_index = MmapIndex::open(test_index_path).expect("open index failed");
        let dictionary = TermDictionary::open(test_fst_path).expect("open dict failed");
        let pipeline = TokenizerPipeline::new();

        // Query: "alpha beta gamma" with top_k = 2
        let top2_res = search_combined_mmap(
            "alpha beta gamma",
            &mmap_index,
            &dictionary,
            &pipeline,
            1.0,
            DEFAULT_EPSILON,
            2,
        );
        assert_eq!(top2_res.len(), 2);
        assert_eq!(top2_res[0].0.hex_id, "doc0");
        assert_eq!(top2_res[1].0.hex_id, "doc1");
        assert!(top2_res[0].1 > top2_res[1].1);

        // Query with top_k = 6 -> all 6 docs returned in order
        let all_res = search_combined_mmap(
            "alpha beta gamma",
            &mmap_index,
            &dictionary,
            &pipeline,
            1.0,
            DEFAULT_EPSILON,
            6,
        );
        assert_eq!(all_res.len(), 6);
        assert_eq!(all_res[0].0.hex_id, "doc0");
        assert_eq!(all_res[1].0.hex_id, "doc1");

        // Top 2 scores match exactly between top_k=2 and top_k=6
        assert!((top2_res[0].1 - all_res[0].1).abs() < 1e-9);
        assert!((top2_res[1].1 - all_res[1].1).abs() < 1e-9);

        let _ = std::fs::remove_file(test_index_path);
        let _ = std::fs::remove_file(test_fst_path);
    }
